1	/**
2	 * REAL 3D LOCAL-TANGENT STEERING (PREPARED, NEVER YET RUN).
3	 *
4	 * WHY THIS MODULE EXISTS
5	 * ----------------------
6	 * The earned-1 capture's walk phase steered in a hard-coded XZ plane: it
7	 * calibrated each ordinary movement key by measuring only [dx, dz], chose keys
8	 * by an XZ dot product, and measured distance with distXZ. On the body the
9	 * Continue boot actually resumed on, the live local up was
10	 * up = (0.9999999999998366, 1.8057e-07, -5.4246e-07) — the +X cube face — and
11	 * the survey end E = [-42, 51.05, 12] lies on the +Y face. In that frame the
12	 * A/D keys move the body predominantly in WORLD Y, so their XZ displacement was
13	 * below the 0.05 threshold and they were recorded as
14	 * calibratedKeyDirections.KeyA = null / KeyD = null. The steering then had only
15	 * W/S to work with, and 144 bursts over 90 387 ms left finalDistToE at
16	 * 94.79 units. That is a PROBE STEERING DEFECT. It is NOT evidence that the
17	 * shipped game failed to restore anything, and nothing here asserts otherwise.
18	 *
19	 * WHAT THIS MODULE DOES
20	 * ---------------------
21	 * Every quantity is 3D. The local tangent plane is built from the ACTUAL live
22	 * `up` published by the shipped commonGround bridge; nothing about the face is
23	 * assumed or hard-coded. Key calibration retains the full 3D displacement of
24	 * each ordinary key, so a key that moves the body purely along world Y on the
25	 * +X face is a MEASURED, NON-ZERO direction rather than a dropped null. When
26	 * the face (and therefore up) changes, `basisStale` says so and the caller
27	 * recalibrates; a stale basis is never silently reused.
28	 *
29	 * WHAT THIS MODULE IS NOT
30	 * -----------------------
31	 *   - it never writes a pose, never calls a rail/autopilot/state setter, never
32	 *     teleports and never fabricates a coordinate;
33	 *   - it makes no claim about whether the game restored correctly;
34	 *   - it has no browser, DOM, GPU or filesystem dependency: pure functions over
35	 *     numbers, so the CPU cases in tangentSteering3d.selftest.mjs exercise the
36	 *     SAME bytes the runtime would import (no mirrored re-implementation).
37	 */
38	
39	const EPS = 1e-9;
40	
41	export const add3 = (a, b) => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
42	export const sub3 = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
43	export const scale3 = (a, s) => [a[0] * s, a[1] * s, a[2] * s];
44	export const dot3 = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
45	export const norm3 = (a) => Math.hypot(a[0], a[1], a[2]);
46	export const dist3 = (a, b) => norm3(sub3(a, b));
47	export const cross3 = (a, b) => [
48	  a[1] * b[2] - a[2] * b[1],
49	  a[2] * b[0] - a[0] * b[2],
50	  a[0] * b[1] - a[1] * b[0]
51	];
52	export function unit3(a) {
53	  const m = norm3(a);
54	  return m < EPS ? null : [a[0] / m, a[1] / m, a[2] / m];
55	}
56	
57	/** Component of `v` lying IN the plane whose normal is `up` (up need not be unit). */
58	export function projectToTangent(v, up) {
59	  const n = unit3(up);
60	  if (!n) return { tangent: [...v], normal: [0, 0, 0], normalScalar: 0, upWasDegenerate: true };
61	  const s = dot3(v, n);
62	  const normal = scale3(n, s);
63	  return { tangent: sub3(v, normal), normal, normalScalar: s, upWasDegenerate: false };
64	}
65	
66	/**
67	 * A right-handed orthonormal basis (u, v) of the tangent plane at `up`. The seed
68	 * axis is the world axis LEAST aligned with up, so the basis is well conditioned
69	 * on every cube face; it is a reporting frame only and no decision depends on
70	 * which seed won.
71	 */
72	export function tangentBasis(up) {
73	  const n = unit3(up);
74	  if (!n) return null;
75	  const axes = [[1, 0, 0], [0, 1, 0], [0, 0, 1]];
76	  let seed = axes[0]; let best = Infinity;
77	  for (const a of axes) {
78	    const align = Math.abs(dot3(a, n));
79	    if (align < best) { best = align; seed = a; }
80	  }
81	  const u = unit3(projectToTangent(seed, n).tangent);
82	  if (!u) return null;
83	  const v = unit3(cross3(n, u));
84	  if (!v) return null;
85	  return { up: n, u, v, seedAxis: seed };
86	}
87	
88	/** Human label for the dominant face of an up vector. Reporting only. */
89	export function faceLabel(up) {
90	  const n = unit3(up);
91	  if (!n) return null;
92	  const names = ['X', 'Y', 'Z'];
93	  let i = 0;
94	  for (let k = 1; k < 3; k++) if (Math.abs(n[k]) > Math.abs(n[i])) i = k;
95	  return `${n[i] >= 0 ? '+' : '-'}${names[i]}`;
96	}
97	
98	/**
99	 * Has the local frame moved far enough that a calibration taken under `oldUp`
100	 * can no longer be trusted? Angle, not face name: a slide across a rounded cube
101	 * edge changes up continuously and must recalibrate before the label flips.
102	 */
103	export function basisStale(oldUp, newUp, { maxTiltDeg = 12 } = {}) {
104	  const a = unit3(oldUp); const b = unit3(newUp);
105	  if (!a || !b) return { stale: true, tiltDeg: null, reason: 'degenerate-up' };
106	  const c = Math.min(1, Math.max(-1, dot3(a, b)));
107	  const tiltDeg = (Math.acos(c) * 180) / Math.PI;
108	  const faceChanged = faceLabel(a) !== faceLabel(b);
109	  return {
110	    stale: tiltDeg > maxTiltDeg || faceChanged,
111	    tiltDeg,
112	    faceChanged,
113	    faceBefore: faceLabel(a),
114	    faceAfter: faceLabel(b),
115	    reason: faceChanged ? 'face-change' : (tiltDeg > maxTiltDeg ? 'tilt-exceeded' : 'fresh')
116	  };
117	}
118	
119	/**
120	 * One measured ordinary-key calibration sample.
121	 *
122	 * The FULL 3D displacement is retained. `movedTangent` is what steering can use;
123	 * `movedNormal` (climb/fall along up) is recorded separately and never counted
124	 * as horizontal progress. A key is `usable` on the 3D tangent magnitude — the
125	 * exact test the XZ version got wrong for A/D on the +X face.
126	 */
127	export function calibrationSample({ key, from, to, up, minUnits = 0.05 }) {
128	  const moved = sub3(to, from);
129	  const proj = projectToTangent(moved, up);
130	  const tangentUnits = norm3(proj.tangent);
131	  return {
132	    key,
133	    from: [...from],
134	    to: [...to],
135	    up: [...up],
136	    face: faceLabel(up),
137	    moved3d: moved,
138	    moved3dUnits: norm3(moved),
139	    movedTangent: proj.tangent,
140	    movedTangentUnits: tangentUnits,
141	    movedNormalUnits: proj.normalScalar,
142	    dir3d: unit3(moved),
143	    dirTangent: unit3(proj.tangent),
144	    usable: tangentUnits > minUnits,
145	    minUnits
146	  };
147	}
148	
149	/**
150	 * Pick the ordinary key whose MEASURED direction, re-projected into the CURRENT
151	 * tangent plane, best matches the wanted tangent direction.
152	 *
153	 * Directions are stored as 3D unit vectors and re-projected on every use, so a
154	 * calibration taken slightly before an up change degrades gracefully instead of
155	 * pointing out of the plane. Returns the full scored table for the record.
156	 */
157	export function chooseKey3d(dirs3d, wantTangent, up, { minScore = 0.15 } = {}) {
158	  const want = unit3(projectToTangent(wantTangent, up).tangent);
159	  const scored = [];
160	  let best = null;
161	  for (const [key, d] of Object.entries(dirs3d ?? {})) {
162	    if (!d) { scored.push({ key, score: null, reason: 'no-measured-displacement' }); continue; }
163	    const p = unit3(projectToTangent(d, up).tangent);
164	    if (!p || !want) { scored.push({ key, score: null, reason: 'degenerate-projection' }); continue; }
165	    const score = dot3(p, want);
166	    scored.push({ key, score, projected: p });
167	    if (!best || score > best.score) best = { key, score, projected: p };
168	  }
169	  const ok = !!best && best.score >= minScore;
170	  return {
171	    key: ok ? best.key : null,
172	    score: best ? best.score : null,
173	    want,
174	    scored,
175	    minScore,
176	    reason: ok ? 'chosen' : (best ? 'no-key-scores-above-threshold' : 'no-usable-key')
177	  };
178	}
179	
180	/**
181	 * Progress of one burst resolved in the CURRENT tangent plane.
182	 *
183	 * alongLeg: motion toward the target along the intended tangent leg.
184	 * lateral:  in-plane motion perpendicular to that leg (a sidestep is not proof
185	 *           the intended direction was clear).
186	 * normal:   motion along up (climb/fall) — reported, never credited as progress.
187	 * dist3dBefore/After: FULL 3D distance to the target; nothing is dropped.
188	 */
189	export function burstProgress3d({ from, to, target, up }) {
190	  const legRaw = projectToTangent(sub3(target, from), up).tangent;
191	  const leg = unit3(legRaw);
192	  const moved = sub3(to, from);
193	  const p = projectToTangent(moved, up);
194	  const along = leg ? dot3(p.tangent, leg) : 0;
195	  const lateralVec = leg ? sub3(p.tangent, scale3(leg, along)) : p.tangent;
196	  return {
197	    alongLeg: along,
198	    lateral: norm3(lateralVec),
199	    normal: p.normalScalar,
200	    grossTangent: norm3(p.tangent),
201	    gross3d: norm3(moved),
202	    legTangentUnits: norm3(legRaw),
203	    dist3dBefore: dist3(from, target),
204	    dist3dAfter: dist3(to, target),
205	    legDegenerate: !leg
206	  };
207	}
208	
209	/**
210	 * Obstacle / stall verdict over the last `window` bursts, in tangent space.
211	 *
212	 * A stall STOPS the route attempt and is reported with its own telemetry. It is
213	 * never answered by a forced action, a teleport, a setter or a bigger timeout.
214	 */
215	export function stallVerdict(bursts, { window = 6, minAlongUnits = 0.25, minDistGainUnits = 0.25 } = {}) {
216	  const recent = bursts.slice(-window);
217	  if (recent.length < window) {
218	    return { stalled: false, reason: 'insufficient-history', samples: recent.length, window };
219	  }
220	  const along = recent.reduce((s, b) => s + (b.alongLeg ?? 0), 0);
221	  const first = recent[0];
222	  const last = recent[recent.length - 1];
223	  const distGain = (first.dist3dBefore ?? 0) - (last.dist3dAfter ?? 0);
224	  const lateral = recent.reduce((s, b) => s + (b.lateral ?? 0), 0);
225	  const normal = recent.reduce((s, b) => s + Math.abs(b.normal ?? 0), 0);
226	  const stalled = along < minAlongUnits && distGain < minDistGainUnits;
227	  return {
228	    stalled,
229	    window,
230	    alongSum: along,
231	    lateralSum: lateral,
232	    normalAbsSum: normal,
233	    dist3dGain: distGain,
234	    minAlongUnits,
235	    minDistGainUnits,
236	    reason: stalled
237	      ? (lateral > along ? 'lateral-only-motion (obstacle or wrong tangent leg)' : 'no-tangent-progress')
238	      : 'progressing'
239	  };
240	}
241	
242	/**
243	 * Separate the two DIFFERENT things the earned-1 record conflated.
244	 *
245	 * auditSupported  — the commonGround bridge's `supported`: whether the AUDITED
246	 *                   chapter plane supports her at that grounded pose. It is
247	 *                   legitimately false when the body is on another cube face,
248	 *                   and false here is NOT a broken-planet-physics claim.
249	 * physicsGrounded — the actual physics ground contact. The shipped bridge
250	 *                   (CommonGroundProbeSnapshot) publishes no such field and
251	 *                   pageReadState exposes none, so unless a hook supplies it at
252	 *                   runtime this stays null and is REPORTED AS A GAP.
253	 */
254	export function footingReading({ auditSupported = null, physicsGrounded = undefined, up = null, auditPlaneFace = '+Y' } = {}) {
255	  const face = up ? faceLabel(up) : null;
256	  const onAuditPlane = face != null && face === auditPlaneFace;
257	  return {
258	    auditSupported,
259	    auditPlaneFace,
260	    observedFace: face,
261	    onAuditPlane,
262	    auditSupportedIsMeaningfulHere: onAuditPlane,
263	    physicsGrounded: physicsGrounded === undefined ? null : physicsGrounded,
264	    physicsGroundedAvailable: physicsGrounded !== undefined,
265	    note: physicsGrounded === undefined
266	      ? 'no physics grounded flag is published by the shipped bridge; this is retained as an OBSERVATION GAP, not inferred from auditSupported'
267	      : 'physics grounded came from a runtime hook and is reported verbatim'
268	  };
269	}
270	
271	// ===========================================================================
272	// GROUND FRAME (pre-GPU correction, producer-earned-continue-3d-prep-review)
273	// ===========================================================================
274	/**
275	 * WHY THIS SECTION EXISTS
276	 * ----------------------
277	 * The prepared walk compared `bodyCentre` against the GROUND target
278	 * E = [-42, 51.05, 12] with an arrival radius of 1.2. The shipped bridge
279	 * (commonGroundDirector.ts:782, :795-797, :1891) publishes TWO different
280	 * points:
281	 *
282	 *   bodyCentre = getPlayerWorldPosition()             — capsule CENTRE
283	 *   bodyPose   = centre - up * CG_PLAYER_GROUND_OFFSET — the FOOT / grounded pose
284	 *
285	 * CG_PLAYER_GROUND_OFFSET = PLAYER_CAPSULE_HALF_HEIGHT + PLAYER_CAPSULE_RADIUS.
286	 * Measured in the earned-1 capture at the post-Continue body:
287	 *   bodyCentre [52.78897476196289, 17.5,               -20]
288	 *   bodyPose   [50.98897476196318, 17.499999674973967, -19.99999902356783]
289	 * i.e. exactly 1.8 units along the live up (+X face). E's y = 51.05 likewise
290	 * matches the EARN-phase FOOT y = 50.9899, not a centre.
291	 *
292	 * So a correctly standing player at E has |centre - E| ~= 1.8 > 1.2: ordinary
293	 * lawful arrival was ARITHMETICALLY IMPOSSIBLE in the prepared probe. The fix
294	 * is to compare the FOOT against ground targets. The radius is NOT widened,
295	 * no coordinate is dropped, and bodyCentre is retained separately.
296	 */
297	
298	/** The shipped ground offset, re-derived from the live snapshot, never assumed. */
299	export function groundFrame({ bodyCentre = null, bodyPose = null, up = null, groundOffsetUnits = null } = {}) {
300	  const n = up ? unit3(up) : null;
301	  const haveBoth = Array.isArray(bodyCentre) && Array.isArray(bodyPose);
302	  const delta = haveBoth ? sub3(bodyCentre, bodyPose) : null;   // centre - foot
303	  const observedOffset = delta ? norm3(delta) : null;
304	  // Is the published centre->foot displacement actually along the published up?
305	  const alongUp = (delta && n) ? dot3(delta, n) : null;
306	  const offAxis = (delta && n && alongUp != null) ? norm3(sub3(delta, scale3(n, alongUp))) : null;
307	  const consistentWithUp = offAxis != null && offAxis <= 1e-3
308	    && (observedOffset == null || Math.abs((alongUp ?? 0) - observedOffset) <= 1e-3);
309	  const matchesPublishedOffset = (groundOffsetUnits != null && observedOffset != null)
310	    ? Math.abs(observedOffset - groundOffsetUnits) <= 1e-3
311	    : null;
312	  return {
313	    centre: haveBoth ? [...bodyCentre] : (bodyCentre ? [...bodyCentre] : null),
314	    foot: bodyPose ? [...bodyPose] : null,
315	    footAvailable: Array.isArray(bodyPose),
316	    up: n,
317	    face: n ? faceLabel(n) : null,
318	    observedOffsetUnits: observedOffset,
319	    publishedOffsetUnits: groundOffsetUnits,
320	    offsetAlongUpUnits: alongUp,
321	    offsetOffAxisUnits: offAxis,
322	    offsetConsistentWithUp: consistentWithUp,
323	    matchesPublishedOffset,
324	    note: 'foot (bodyPose) is the frame for GROUND targets; centre is retained for the record and is never compared to a ground target'
325	  };
326	}
327	
328	/**
329	 * Arrival at a GROUND target, decided on the FOOT in full 3D.
330	 * `arriveUnits` is the caller's existing radius and is never widened here.
331	 */
332	export function groundTargetArrival({ bodyCentre = null, bodyPose = null, up = null, groundOffsetUnits = null, target, arriveUnits }) {
333	  const gf = groundFrame({ bodyCentre, bodyPose, up, groundOffsetUnits });
334	  if (!gf.footAvailable) {
335	    return {
336	      arrived: false, usable: false, reason: 'foot-pose-unavailable',
337	      frame: gf, target: [...target], arriveUnits,
338	      distFootToTarget: null,
339	      distCentreToTarget: gf.centre ? dist3(gf.centre, target) : null
340	    };
341	  }
342	  const d = dist3(gf.foot, target);
343	  return {
344	    arrived: d <= arriveUnits,
345	    usable: true,
346	    reason: d <= arriveUnits ? 'foot-within-radius' : 'foot-outside-radius',
347	    frame: gf,
348	    target: [...target],
349	    arriveUnits,
350	    distFootToTarget: d,
351	    // Diagnostic ONLY. This is the number the prepared probe wrongly gated on.
352	    distCentreToTarget_diagnosticOnly: gf.centre ? dist3(gf.centre, target) : null
353	  };
354	}
355	
356	/**
357	 * The pre-[F] authorization. EVERY condition must hold on CURRENT readings:
358	 *   - the FOOT is at the ground target within the existing radius;
359	 *   - the beat is the expected CURRENT beat (a stale beat never authorizes);
360	 *   - audit-plane support is true WHERE audit support is meaningful (i.e. the
361	 *     body is on the audited plane). Off that plane `auditSupported=false` is
362	 *     NOT a physics verdict and is NOT silently treated as grounded either —
363	 *     it refuses, and says why;
364	 *   - the shipped prompt is actually offering [F].
365	 * Nothing here presses anything, forces anything or invents a physics contact.
366	 */
367	export function groundedActionGate({
368	  bodyCentre = null, bodyPose = null, up = null, groundOffsetUnits = null,
369	  target, arriveUnits, beat = null, expectBeat = null,
370	  auditSupported = null, physicsGrounded = undefined, promptOffersF = false
371	} = {}) {
372	  const arrival = groundTargetArrival({ bodyCentre, bodyPose, up, groundOffsetUnits, target, arriveUnits });
373	  const footing = footingReading({ auditSupported, physicsGrounded, up });
374	  const problems = [];
375	  if (!arrival.usable) problems.push(`no published foot pose (${arrival.reason}); a ground target cannot be judged from bodyCentre`);
376	  else if (!arrival.arrived) problems.push(`foot is ${arrival.distFootToTarget.toFixed(3)}u from the ground target, outside the existing ${arriveUnits}u radius`);
377	  if (arrival.usable && arrival.frame.offsetConsistentWithUp === false) {
378	    problems.push('published centre->foot offset is not along the published up; the target frames do not match and no arrival is asserted');
379	  }
380	  if (expectBeat != null && beat !== expectBeat) problems.push(`beat is ${JSON.stringify(beat)}, not the current expected ${JSON.stringify(expectBeat)} (stale beat never authorizes the action)`);
381	  if (footing.physicsGroundedAvailable) {
382	    if (footing.physicsGrounded !== true) problems.push('the runtime-published physics grounded flag is not true');
383	  } else if (footing.onAuditPlane) {
384	    if (auditSupported !== true) problems.push('audit-plane support is not true at the grounded pose (meaningful here: the body IS on the audited plane)');
385	  } else {
386	    problems.push(`grounding is UNVERIFIABLE here: the body is on face ${footing.observedFace}, off the audited ${footing.auditPlaneFace} plane, and no physics grounded flag is published. auditSupported=${JSON.stringify(auditSupported)} is not a physics verdict, so it is neither accepted nor read as broken physics`);
387	  }
388	  if (!promptOffersF) problems.push('the shipped prompt is not offering [F]');
389	  return {
390	    ok: problems.length === 0,
391	    problems,
392	    arrival,
393	    footing,
394	    beat,
395	    expectBeat,
396	    promptOffersF,
397	    decidedOn: 'foot (bodyPose) vs ground target, full 3D, existing radius unchanged'
398	  };
399	}
